import { BuildContext, Component, HtmlElement, StatelessComponent, StyleBuilder } from "@equantic/runtime";
import { Children } from "./Children";
import { Dictionary } from "./Dictionary";
import { DynamicElement } from "./DynamicElement";
import { Text } from "./Text";

export class Button extends StatelessComponent {
    build(context: BuildContext) {
        let theme = context.getService('IAppTheme');let buttonTheme = theme?.button;let classValue = StyleBuilder.create(buttonTheme?.base).add(buttonTheme?.getVariant(this.variant)).add(buttonTheme?.getSize(this.size)).add(this.className).build();let attrs = { ["type"]: this.type, ["class"]: classValue };if (this.disabled || this.loading) attrs['disabled'] = 'true';if (this.loading) attrs['data-loading'] = 'true';let element = new DynamicElement({ tagName: 'button', customAttributes: attrs, customEvents: this.buildEvents() });if (this.loading) {element.children.push(this.createSpinner());}if ((this.children.length > 0)) {for (const child of this.children) {element.children.push(child);}} else if (this.text != null) {element.children.push(new Text(this.text));}return element;
    }

}

